insert into practice_exercises (id, subject_name, level, title, source) values
  ('01d96aa0-2948-45ed-b879-b9a67585dcbc', $$Natuurkunde$$, $$HAVO$$, $$Elektrische doorstroomverwarmer$$, $$HAVO Natuurkunde 2017-I$$),
  ('d28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$Natuurkunde$$, $$HAVO$$, $$Molybdeen-99$$, $$HAVO Natuurkunde 2017-I$$),
  ('a65d159e-e94a-4c9a-a319-f133e523042b', $$Natuurkunde$$, $$HAVO$$, $$Road-train$$, $$HAVO Natuurkunde 2017-I$$),
  ('297218f0-d74b-4025-9fac-9fc4e0ef864b', $$Natuurkunde$$, $$HAVO$$, $$Metaalmoeheid$$, $$HAVO Natuurkunde 2017-I$$),
  ('5eef8692-6165-4acd-b997-14f4431b2b77', $$Natuurkunde$$, $$HAVO$$, $$Naaldjes rond de aarde$$, $$HAVO Natuurkunde 2017-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('7a759cca-fa4e-41d9-85bf-c3756e9de17e', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$figuur 1 en 2 — oud type (weerstandsdraad om de waterleiding gewikkeld) en nieuw type (weerstandsdraad loopt door de waterleiding heen) doorstroomverwarmer$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-context1.png$$, 461, $$Een elektrische doorstroomverwarmer is een apparaatje dat in de koudwaterleiding gemonteerd wordt om koud water op te warmen.

In een oud type doorstroomverwarmer is een weerstandsdraad om de waterleiding gewikkeld. Zie figuur 1. De weerstandsdraad dient als verwarmingselement. In nieuwe types loopt de weerstandsdraad door de waterleiding heen en wordt direct omspoeld door het leidingwater. Zie figuur 2.$$, 'inline'),
  ('e9a17224-d940-4faa-b835-9cf3d87bada4', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$vuistregel P = 70·debiet·ΔT; technische gegevens: 230 V, maximaal vermogen 5000 W, maximaal debiet 2,9 L/min$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-context2.png$$, 465, $$Om de juiste elektrische doorstroomverwarmer te kiezen wordt de volgende vuistregel gebruikt:
P = 70·debiet·ΔT
Het debiet is het aantal liter water dat per minuut door de doorstroomverwarmer wordt verwarmd.

In een folder van een bepaald type doorstroomverwarmer staan de volgende technische gegevens:
Technische gegevens
spanning: 230 V
maximaal vermogen: 5000 W
maximaal debiet: 2,9 L/min$$, 'inline'),
  ('cbc8c442-9392-421f-b5f8-1369f2851457', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$keuze uit zekeringen van 16 A, 20 A, 25 A of 40 A$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-context3.png$$, 432, $$Deze doorstroomverwarmer moet aangesloten worden op een zekering. Er kan gekozen worden uit zekeringen van 16 A, 20 A, 25 A of 40 A.$$, 'inline'),
  ('8d40193d-85b3-4058-9c92-4fd67c89381b', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$figuur 3 — schakelschema met vier identieke weerstandsdraden R₁ t/m R₄ in de waterleiding, schakelaars P en Q$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-context4.png$$, 447, $$In de doorstroomverwarmer wordt het vermogen automatisch aangepast aan de waterbehoefte. In de geïsoleerde kunststof waterleiding zijn hiervoor vier identieke weerstandsdraden R₁ tot en met R₄ als verwarmingselementen gemonteerd. Zie figuur 3.$$, 'inline'),
  ('9f0715b4-89af-4143-a528-77bd8b616b20', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$bij weinig watergebruik is alleen schakelaar P gesloten; bij grotere vraag zijn P en Q beide gesloten$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-context5.png$$, 444, $$Bij weinig watergebruik is alleen schakelaar P gesloten. Als de vraag naar water groter is, zijn beide schakelaars P en Q gesloten.
Over deze schakeling staan op de uitwerkbijlage drie zinnen.$$, 'inline'),
  ('1179c218-04e0-4b91-b042-2bc7e7a3a66b', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$uitwerkbijlage vraag 4 — drie zinnen met aan te kruisen alternatief over weerstand, stroomsterkte en vermogen als schakelaar Q ook gesloten wordt$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-uitwerkbijlage-vraag4.png$$, 448, $$4 Omcirkel in elke zin het juiste alternatief.

Als schakelaar Q ook wordt gesloten, geldt dat:
− de totale weerstand van de doorstroomverwarmer toeneemt / afneemt / gelijk blijft.
− de totale stroomsterkte door de weerstandsdraden samen daardoor toeneemt / afneemt / gelijk blijft.
− het vermogen van de doorstroomverwarmer daardoor toeneemt / afneemt / gelijk blijft.$$, 'uitwerkbijlage'),
  ('423b0e9b-30e6-42b4-a8ef-40e22eda3404', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$de temperatuur van het uitstromende water verandert als het debiet verandert$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-context6.png$$, 441, $$De temperatuur van het uitstromende water zal veranderen als het debiet verandert.$$, 'inline'),
  ('02854d94-6ca0-48ca-b385-9e31ee8a0812', '01d96aa0-2948-45ed-b879-b9a67585dcbc', $$figuur 4 — uitvergroting: kortste afstand weerstandsdraad tot uitstroomopening 5,0 cm, diameter waterkolom 15 mm, soortelijke weerstand water 1,3·10⁵ Ωm$$,
   $$natuurkunde-havo-2017-i-elektrische-doorstroomverwarmer-context7.png$$, 440, $$De weerstandsdraden bevinden zich ongeïsoleerd in het water. Dat lijkt gevaarlijk. De kortst mogelijke afstand tussen een weerstandsdraad en de uitstroomopening met het aan te raken water is 5,0 cm. De diameter van de waterkolom in de leiding is 15 mm. Zie schematisch in figuur 3 en uitvergroot in figuur 4. Het water heeft een soortelijke weerstand van 1,3·10⁵ Ωm.
De weerstand van de vinger wordt verwaarloosd.$$, 'inline'),
  ('99a8ca38-40a4-4654-a4e6-efbf6d17c6ed', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$kerncentrale Petten produceert molybdeen-99 (Mo-99) door een neutron in de kern van een andere isotoop te schieten; reactie deels op uitwerkbijlage$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-context1.png$$, 437, $$In Petten staat een kerncentrale waar isotopen voor medische toepassingen worden geproduceerd. Eén van de belangrijkste producten is molybdeen-99 (Mo-99).

Mo-99 wordt geproduceerd door een neutron in de kern van een andere isotoop te schieten. Op de uitwerkbijlage staat de reactie hiervan deels weergegeven.$$, 'inline'),
  ('66fefb2c-616e-45ce-a94e-79cbaaeca1bd', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$uitwerkbijlage vraag 7 — onvolledige kernreactievergelijking: ....+....n → ⁹⁹Mo$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-uitwerkbijlage-vraag7.png$$, 345, $$7
.... .... + .... n → ⁹⁹Mo$$, 'uitwerkbijlage'),
  ('f1ba5482-b674-4f56-88ac-9bc71c4c8906', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$Mo-99 vervalt onderweg deels tot technetium-99m (Tc-99m); wekelijks nieuwe voorraad Mo-99 in ziekenhuizen$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-context2.png$$, 446, $$Mo-99 wordt naar ziekenhuizen getransporteerd. Ondertussen vervalt een deel tot technetium-99m (Tc-99m), dat gebruikt wordt voor medische behandelingen. Iedere keer als men Tc-99m nodig heeft voor een behandeling, wordt dit afgescheiden van het molybdeen.
In ziekenhuizen wordt wekelijks een nieuwe voorraad Mo-99 aangevoerd.$$, 'inline'),
  ('1df78116-5930-4a2a-aaec-1135c2f9f7af', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$Tc-99m is metastabiel; bij verval van Tc-99m naar Tc-99 komt een foton vrij met energie 0,141 MeV$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-context3.png$$, 432, $$Tc-99m is metastabiel. Dit betekent dat de protonen en neutronen in de kern van een Tc-99m atoom zich kunnen herschikken tot een toestand met een lagere energie. Bij het verval van Tc-99m naar Tc-99 komt een foton vrij met een energie van 0,141 MeV.$$, 'inline'),
  ('4aaa15e1-88ff-4803-aeda-879a1ea15926', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$dosis moet zo laag mogelijk blijven; verval in eerste 12 uur van Tc-99m en twee andere tracers op uitwerkbijlage; 3,0 uur na toedienen (N = 1,0·10¹² op t = 0 uur) minimaal 2,0·10⁷ Bq nodig$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-context4.png$$, 436, $$Door deze fotonen is Tc-99m geschikt als tracer.
Een voorwaarde voor een radioactieve tracer is dat de totale dosis voor de patiënt zo laag mogelijk blijft. Een arts kan voor een behandeling kiezen uit tracers met verschillende halveringstijden.
In de figuur op de uitwerkbijlage staat het verval in de eerste 12 uur voor Tc-99m. In de figuur is ook het verval voor twee tracers met andere halveringstijden weergegeven.
Voor een bepaalde diagnose is 3,0 uur na het toedienen van de radioactieve tracer (N = 1,0·10¹² op t = 0 uur) een activiteit nodig van minimaal 2,0·10⁷ Bq.$$, 'inline'),
  ('f21d442e-3d45-4d73-99d1-0ef2e80951bb', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$uitwerkbijlage vraag 10 — (N,t)-vervalgrafiek eerste 12 uur voor Tc-99m en twee tracers met T½ = 60 uur en T½ = 0,6 uur$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-uitwerkbijlage-vraag10.png$$, 458, $$10
(N,t)-diagram met het verval in de eerste 12 uur van Tc-99m (T½ ≈ 6 uur) en van twee andere tracers met halveringstijden van 60 uur en 0,6 uur, uitgaande van N = 1,0·10¹² op t = 0 uur.$$, 'uitwerkbijlage'),
  ('a76b9b50-574e-4a19-94d0-43271495e437', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$figuur 1 — fotondetectoren p en q rond de patiënt meten intensiteit; figuur 2 — (I,s)-diagram intensiteit versus afgelegde afstand in weefsel$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-context5.png$$, 463, $$De plaats van de tracer kan worden bepaald door twee fotondetectoren p en q rond de patiënt te plaatsen, zie figuur 1. Deze detectoren meten de intensiteit van de uitgezonden straling.

De detector meet een lagere intensiteit I van de straling als de afstand tot de tracer groter is. Het verband tussen de intensiteit van de straling en de afstand die deze straling heeft afgelegd in menselijk weefsel is weergegeven in figuur 2.$$, 'inline'),
  ('abf0cc45-dacc-497f-a5b9-81dfffdf9721', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$figuur 3 — detectoren p en q op 32 cm afstand, op schaal (1 cm komt overeen met 5 cm) met vier mogelijke tracerposities a, b, c, d; intensiteit bij p is 4× die bij q$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-context6.png$$, 444, $$Tijdens een meting worden detectoren p en q tegen de patiënt geschoven. De afstand tussen p en q is dan 32 cm. In figuur 3 is dit schematisch en op schaal weergegeven. In de tekening komt 1 cm overeen met 5 cm in werkelijkheid.

De intensiteit I die detector p meet, is 4 keer zo groot als de intensiteit I die detector q meet.
Figuren 2 en 3 staan ook op de uitwerkbijlage.$$, 'inline'),
  ('b91423af-67ce-43bf-81a5-702410bc7ef7', 'd28f4b83-5ca7-41a7-b420-647b32bbe8ef', $$uitwerkbijlage vraag 12 — figuur 2 ((I,s)-diagram) en figuur 3 (detectoren p, q met posities a, b, c, d, 32 cm) ter beredenering$$,
   $$natuurkunde-havo-2017-i-molybdeen-99-uitwerkbijlage-vraag12.png$$, 468, $$12
Figuur 2 ((I,s)-diagram) en figuur 3 (detectoren p en q op 32 cm afstand met posities a, b, c, d) ter ondersteuning van de beredenering.$$, 'uitwerkbijlage'),
  ('b4ced7fc-2d49-4942-884e-86adf086695b', 'a65d159e-e94a-4c9a-a319-f133e523042b', $$road-train: vrachtwagen met meerdere aanhangers, gebruikt in Australië; maximale snelheid 90 km h⁻¹; kaart met mogelijke routes op uitwerkbijlage$$,
   $$natuurkunde-havo-2017-i-road-train-context1.png$$, 464, $$Een 'road-train' is een lange combinatie die bestaat uit een vrachtwagen met meerdere aanhangers, zie figuur 1.

Road-trains worden vooral veel gebruikt voor de lange reisafstanden in Australië. De maximale snelheid voor een road-train is 90 km h⁻¹. Op de uitwerkbijlage is een kaart van een deel van Australië gegeven met mogelijke routes voor road-trains.$$, 'inline'),
  ('c0ef0c0f-3717-4153-a944-25086551d9c1', 'a65d159e-e94a-4c9a-a319-f133e523042b', $$uitwerkbijlage vraag 13 — kaart van Zuid-Australië met wegen tussen Port Augusta, Port Lincoln en omliggende plaatsen, schaal 0-60-120 km$$,
   $$natuurkunde-havo-2017-i-road-train-uitwerkbijlage-vraag13.png$$, 432, $$13
Kaart van een deel van Zuid-Australië met de wegen tussen Port Augusta, Streaky Bay, Wudinna, Whyalla, Elliston, Cowell, Port Lincoln en andere plaatsen, met schaalbalk (0, 60, 120 km).$$, 'uitwerkbijlage'),
  ('c950555f-9a95-4506-abcf-f3b423b20521', 'a65d159e-e94a-4c9a-a319-f133e523042b', $$figuur 2 — (h,s)-diagram van een licht glooiende weg met trajecten ab, bc en cd, afgelegd met constante snelheid 90 km h⁻¹; road-train massa 160 ton$$,
   $$natuurkunde-havo-2017-i-road-train-context2.png$$, 435, $$Een deel van de route gaat over een licht glooiende weg. De hele weg wordt met een constante snelheid van 90 km h⁻¹ afgelegd.
In figuur 2 staat de hoogte van deze weg als functie van de afgelegde afstand uitgezet.

In deze figuur zijn drie trajecten ab, bc en cd aangegeven. De motor van een road-train met een massa van 160 ton moet op traject ab meer vermogen leveren dan op een horizontale weg.$$, 'inline'),
  ('ecbd75bb-b2a1-487e-9499-bf4db1bf3702', 'a65d159e-e94a-4c9a-a319-f133e523042b', $$op de uitwerkbijlage staan drie beweringen over de trajecten ab, bc en cd$$,
   $$natuurkunde-havo-2017-i-road-train-context3.png$$, 483, $$Op de uitwerkbijlage staan drie beweringen over deze drie trajecten van de route van de road-train.$$, 'inline'),
  ('9a3d4d69-b126-47a5-85a4-42f501ebba05', 'a65d159e-e94a-4c9a-a319-f133e523042b', $$uitwerkbijlage vraag 15 — tabel met drie beweringen over zwaartekracht, normaalkracht en tijdsduur op de trajecten ab, bc, cd, aan te kruisen juist/onjuist$$,
   $$natuurkunde-havo-2017-i-road-train-uitwerkbijlage-vraag15.png$$, 491, $$15
bewering / juist / onjuist
Op traject ab is de zwaartekracht op de road-train het grootst.
De normaalkracht op de road-train is het grootst op traject bc.
De tijd die nodig is om traject cd af te leggen is het langst.$$, 'uitwerkbijlage'),
  ('eca5ee4c-ee9a-47d9-9f40-7fb6a123d525', 'a65d159e-e94a-4c9a-a319-f133e523042b', $$figuur 3 — tabel met testresultaten (massa, tijd, snelheid, kracht, kinetische energie) voor vrachtwagen (40 ton) en road-train (160 ton) over eerste 100 m, twee waarden voor road-train ontbreken; twee beweringen van een onderzoeker$$,
   $$natuurkunde-havo-2017-i-road-train-context4.png$$, 466, $$Road-trains zijn veel zwaarder dan normale vrachtwagens. In het verkeer kan dit een groter risico opleveren.
De Australische regering heeft daarom een onderzoek laten uitvoeren naar verschillen in rijeigenschappen tussen een road-train en een gewone vrachtwagen op een vlakke weg. In een bepaalde test werden na de eerste 100 m van een traject de tijd en de snelheid gemeten. De beginsnelheid was 0 m s⁻¹, de versnelling was constant.
In figuur 3 staat een tabel met de resultaten van dit onderzoek. Twee waarden ontbreken nog in deze tabel.

figuur 3:
massa (ton) | tijd (s) | snelheid (m s⁻¹) | kracht (kN) | kinetische energie (MJ)
vrachtwagen: 40 | 19,2 | 10,4 | 22 | 2,2
road-train: 160 | 28,2 | 7,09 | ? | ?

Een onderzoeker beweerde:
1 De motor van de road-train van 160 ton levert over deze 100 m meer kracht dan de motor van de vrachtwagen van 40 ton.
2 De road-train van 160 ton heeft na 100 m meer kinetische energie dan de vrachtwagen van 40 ton.$$, 'inline'),
  ('39eb55bb-8d23-4109-809e-cb947ae6878c', 'a65d159e-e94a-4c9a-a319-f133e523042b', $$noodstop vanaf 60 km h⁻¹ tot stilstand; figuur 4 — (v,t)-diagram van vrachtwagen (40 ton) en road-train (160 ton)$$,
   $$natuurkunde-havo-2017-i-road-train-context5.png$$, 446, $$In een andere test werd er met de twee voertuigen een noodstop gemaakt vanaf 60 km h⁻¹ tot stilstand.
In figuur 4 is het (v,t)-diagram hiervan weergegeven.$$, 'inline'),
  ('826dcc01-d6d2-4ec9-a42a-8113341c5a31', '297218f0-d74b-4025-9fac-9fc4e0ef864b', $$figuur 1 — fietswiel met spaken; roestvrijstalen spaak voorgespannen op 190 MPa (= 190·10⁶ N m⁻²), doorsnede 2,63 mm²$$,
   $$natuurkunde-havo-2017-i-metaalmoeheid-context1.png$$, 460, $$Soms kan een spaak in een fietswiel plotseling breken, zie figuur 1. In een onderzoek naar de oorzaak hiervan, worden roestvrijstalen spaken in een fietswiel gemonteerd. Als een spaak in het fietswiel wordt gemonteerd, wordt de spaak ook gespannen. Dit wordt voorspannen genoemd.
In dit onderzoek krijgt een roestvrijstalen spaak een spanning van 190 MPa (= 190·10⁶ N m⁻²). De doorsnede van de spaak is 2,63 mm².$$, 'inline'),
  ('02c2efb5-3c7c-4135-8933-d003f267f4ed', '297218f0-d74b-4025-9fac-9fc4e0ef864b', $$in het onderzoek is de spanning in de spaak gemeten tijdens het fietsen; figuur 3 — (σ,t)-diagram, ook op de uitwerkbijlage$$,
   $$natuurkunde-havo-2017-i-metaalmoeheid-context3.png$$, 438, $$In het onderzoek is de spanning in de spaak gemeten tijdens het fietsen. In figuur 3 zijn de meetresultaten weergegeven.
Figuur 3 is ook op de uitwerkbijlage weergegeven.$$, 'inline'),
  ('8969050c-e4b3-4270-afab-9d87e871bfb5', '297218f0-d74b-4025-9fac-9fc4e0ef864b', $$spanningsamplitude σₐ = (σmax−σmin)/2; levensduur N = aantal wielomwentelingen tot breuk; figuur 4 — (σₐ,N)-diagram met niet-lineaire N-as, ook op de uitwerkbijlage$$,
   $$natuurkunde-havo-2017-i-metaalmoeheid-context4.png$$, 438, $$Bij metaalmoeheid hangt de levensduur van een spaak af van de spanningsamplitude.
Voor de spanningsamplitude geldt: σₐ = (σmax − σmin) / 2
De levensduur N is het aantal wielomwentelingen dat de spaak kan ondergaan tot hij breekt.

In figuur 4 is het (σₐ,N)-diagram van de spaak in dit onderzoek gegeven. De horizontale as heeft een niet-lineaire schaalverdeling.
Figuur 4 staat ook op de uitwerkbijlage.$$, 'inline'),
  ('ed39e532-08c5-4b6e-a45a-0a02aa72147c', '297218f0-d74b-4025-9fac-9fc4e0ef864b', $$uitwerkbijlage vraag 20 en 21 — figuur 3, (σ,t)-diagram van de spanning in de spaak tijdens het fietsen$$,
   $$natuurkunde-havo-2017-i-metaalmoeheid-uitwerkbijlage-vraag21.png$$, 440, $$20 en 21
(σ,t)-diagram van de gemeten spanning in de spaak tijdens het fietsen (σ in MPa tegen t in s, 0 tot 2,0 s).$$, 'uitwerkbijlage'),
  ('f555e7f6-3122-43d9-a7fe-adcdbef0e4d1', '297218f0-d74b-4025-9fac-9fc4e0ef864b', $$uitwerkbijlage vraag 20 en 22 — figuur 4, (σₐ,N)-diagram met niet-lineaire N-as$$,
   $$natuurkunde-havo-2017-i-metaalmoeheid-uitwerkbijlage-vraag22.png$$, 402, $$20 en 22
(σₐ,N)-diagram van de spaak (σₐ in MPa tegen N, niet-lineaire schaal van 1·10⁴ tot 1·10⁷).$$, 'uitwerkbijlage'),
  ('fa31a53b-2c99-43cf-96e5-399b3186fe18', '297218f0-d74b-4025-9fac-9fc4e0ef864b', $$spaak strakker aangespannen; nieuwe spanningsamplitude σₐ = 120 MPa; diameter gebruikte wiel 70 cm$$,
   $$natuurkunde-havo-2017-i-metaalmoeheid-context5.png$$, 438, $$Vervolgens wordt de spaak strakker aangespannen. De voorspanning en de spanningsamplitude worden hierdoor verhoogd. De spanningsamplitude σₐ wordt nu 120 MPa.
De diameter van het gebruikte wiel is 70 cm.$$, 'inline'),
  ('ffd582d4-51fe-46ac-a5ba-2c360d46e854', '5eef8692-6165-4acd-b997-14f4431b2b77', $$figuur 1 — artist’s impression van de ring van 480·10⁶ koperen naaldjes rond de aarde (9 mei 1963); naaldje: cilindervormig, 1,8 cm lang, massa 40 µg; diameter mensenhaar 50 µm$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-context1.png$$, 442, $$In de tijd van de Koude Oorlog droomde het Amerikaanse leger van communicatiesatellieten in de ruimte.

Men kwam op het idee om een kunstmatige ring van kleine koperen naaldjes rond de aarde te maken. Via die naaldjes kon er dan met radiosignalen over grote afstanden gecommuniceerd worden.

Op 9 mei 1963 werden 480·10⁶ kleine koperen naaldjes in een ring om de aarde gebracht. Figuur 1 geeft een artist's impression van deze ring om de aarde.
Elk cilindervormig naaldje was 1,8 cm lang en had een massa van 40 µg.

De diameter van een mensenhaar is 50 µm.$$, 'inline'),
  ('6d71e1f0-888b-4543-9a58-ff880cd5f495', '5eef8692-6165-4acd-b997-14f4431b2b77', $$lengte naaldje = helft van de golflengte van de gebruikte microgolfstraling$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-context2.png$$, 479, $$De lengte van een naaldje was gelijk aan de helft van de golflengte van de microgolfstraling die voor de communicatie werd gebruikt.$$, 'inline'),
  ('d6ad0f6c-e910-4b8c-b429-d33eb92150a1', '5eef8692-6165-4acd-b997-14f4431b2b77', $$naaldje werkt als antenne en zendt straling opnieuw uit; datasnelheid 2,0·10⁴ bits per seconde; foto van 5 MB, 1 byte = 8 bits$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-context3.png$$, 444, $$Als een naaldje door deze straling werd geraakt, ging het als een antenne werken. Het naaldje zond dan deze straling weer uit.
Het lukte om signalen met 2,0·10⁴ bits per seconde te verzenden via de naaldjes in de ruimte. Een digitale foto van nu is 5 megabyte (MB). In het dataverkeer is 1 byte gelijk aan 8 bits.$$, 'inline'),
  ('a67bab58-5d25-4b03-a982-d6fc41db0de0', '5eef8692-6165-4acd-b997-14f4431b2b77', $$naaldjes op 3,70·10³ km boven de evenaar in cirkelbaan; v = √(GM/r) met G = gravitatieconstante, M = massa aarde, r = straal cirkelbaan$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-context4.png$$, 444, $$De naaldjes bewogen op 3,70·10³ km boven de evenaar in een cirkelbaan rond de aarde. Voor de snelheid van een naaldje geldt:
v = √(GM/r)
Hierin is:
− G de gravitatieconstante;
− M de massa van de aarde;
− r de straal van de cirkelbaan.$$, 'inline'),
  ('d37cab74-6283-4dc9-8943-87aa608d71f1', '5eef8692-6165-4acd-b997-14f4431b2b77', $$veel naaldjes nodig omdat de omlooptijd van een naaldje korter was dan de rotatietijd Taarde van de aarde om haar eigen as$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-context5.png$$, 440, $$Er waren veel naaldjes nodig om gedurende langere tijd signalen te kunnen versturen. Een enkel naaldje was maar kort binnen bereik van de zender op aarde. Dit was omdat de omlooptijd van een naaldje om de aarde korter was dan de tijd Taarde die de aarde nodig heeft voor een rotatie om haar eigen as.$$, 'inline'),
  ('d8af9994-6480-47db-bff7-90cf5ae502d9', '5eef8692-6165-4acd-b997-14f4431b2b77', $$baanstraal en snelheid van een naaldje werden constant beschouwd$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-context6.png$$, 433, $$De baanstraal en de snelheid van een naaldje werden constant beschouwd.$$, 'inline'),
  ('43f2a866-0111-4da2-843b-a5893be0ce08', '5eef8692-6165-4acd-b997-14f4431b2b77', $$uitwerkbijlage vraag 27 — twee zinnen met aan te kruisen alternatief over hoogte t.o.v. geostationaire baan en verhouding middelpuntzoekende kracht/gravitatiekracht$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-uitwerkbijlage-vraag27.png$$, 436, $$27 Omcirkel in elke zin het juiste alternatief.
− De naaldjes bevonden zich hoger dan / in / lager dan de geostationaire baan.
− De middelpuntzoekende kracht op een naaldje was groter dan / kleiner dan / gelijk aan de gravitatiekracht op een naaldje.$$, 'uitwerkbijlage'),
  ('7e4bf55e-7740-47e8-b3bb-7b3aa0ea4f28', '5eef8692-6165-4acd-b997-14f4431b2b77', $$bijna alle 480·10⁶ naaldjes gelijkmatig terechtgekomen op een strook die 20% van het aardoppervlak beslaat$$,
   $$natuurkunde-havo-2017-i-naaldjes-rond-de-aarde-context7.png$$, 495, $$De ring van naaldjes bleef uiteindelijk niet intact.
Inmiddels zijn bijna alle 480·10⁶ naaldjes gelijkmatig verdeeld weer op de aarde terechtgekomen op een strook die 20% van het aardoppervlak in beslag neemt. De NASA was van plan om enkele naaldjes te gaan zoeken om te bestuderen wat het effect van een verblijf in de ruimte geweest is. Om de haalbaarheid van deze zoektocht te beoordelen was het voor de NASA belangrijk in te schatten hoeveel naaldjes er per km² te vinden zouden zijn.$$, 'inline');

